import java.util.Scanner;

public class Main {
    public static int computeGCD(int a, int b) {
        return b == 0 ? a : computeGCD(b, a % b);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int limit = sc.nextInt();
        double minDiff = 1e9;
        int ansNum = 0, ansDen = 1;
        double ratio = (double) x / y;

        for (int i = 1; i <= limit; ++i) {
            int b = (int) ((long) x * i / y);
            double a = (double) b / i;
            double aMinus = (double) (Math.abs(b - 1)) / i;
            double aPlus = (double) (b + 1) / i;

            if (Math.abs(ratio - a) < minDiff) {
                ansNum = b;
                ansDen = i;
                minDiff = Math.abs(ratio - a);
            }
            if (Math.abs(ratio - aMinus) < minDiff) {
                ansNum = Math.abs(b - 1);
                ansDen = i;
                minDiff = Math.abs(ratio - aMinus);
            }
            if (Math.abs(ratio - aPlus) < minDiff) {
                ansNum = b + 1;
                ansDen = i;
                minDiff = Math.abs(ratio - aPlus);
            }
        }

        if (Math.abs(1.0 - ratio) <= (Math.abs((double) ansNum / ansDen) - ratio) + 1e-9) {
            ansNum = 1;
            ansDen = 1;
        }

        int g = computeGCD(ansNum, ansDen);
        System.out.println((ansNum / g) + "/" + (ansDen / g));
        sc.close();
    }
}
